const root=$input.first().json||{};
const src=root.source || root.input?.source || {};
const rules=root.mapping || root.input?.mapping || [];
const get=(obj,path)=>String(path||'').split('.').filter(Boolean).reduce((v,k)=>v==null?undefined:v[k],obj);
const set=(obj,path,value)=>{const parts=String(path).split('.').filter(Boolean);let cur=obj;parts.forEach((p,i)=>{if(i===parts.length-1)cur[p]=value;else cur=cur[p]??={};});};
const issues=[]; const mapped={};
const typeOf=v=>Array.isArray(v)?'array':v===null?'null':typeof v;
if(!Array.isArray(rules)||!rules.length) return [{json:{success:false,component_id:'C6-D',component_version:'v1',issues:[{severity:'high',code:'NO_MAPPING_RULES',message:'mapping must contain at least one rule.'}],mapped_preview:{},next_action:'provide_mapping_contract',error:{code:'NO_MAPPING_RULES',message:'No mapping rules supplied.'}}}];
for(const r of rules){const value=get(src,r.source_path);if((value===undefined||value===null||value==='') && r.required) issues.push({severity:'high',code:'MISSING_REQUIRED_SOURCE',source_path:r.source_path,target_path:r.target_path,message:'Required source value is missing.'});if(value!==undefined && r.type && typeOf(value)!==r.type) issues.push({severity:'medium',code:'TYPE_MISMATCH',source_path:r.source_path,target_path:r.target_path,expected_type:r.type,actual_type:typeOf(value),message:'Source type does not match mapping contract.'});if(value!==undefined && r.target_path) set(mapped,r.target_path,value);if(!r.target_path) issues.push({severity:'high',code:'MISSING_TARGET_PATH',source_path:r.source_path,message:'Mapping rule has no target_path.'});}
const blocking=issues.some(i=>i.severity==='high');
return [{json:{success:true,component_id:'C6-D',component_version:'v1',mapping_status:blocking?'invalid':issues.length?'warning':'valid',issues,mapped_preview:mapped,next_action:blocking?'repair_mapping':'mapping_ready',error:null}}];
